INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-1', 'theorist', 'th-new-1', 'ali-shariati', 'علی شریعتی', 'Ali Shariati', 'theorist', 'علی شریعتی (۱۹۳۳–۱۹۷۷) جامعه‌شناس، فیلسوف و پژوهشگر ایرانی با مدرک دکترای جامعه‌شناسی از دانشگاه پاریس است. او از مهم‌ترین نظریه‌پردازان ایرانیِ «بازگشت به اصل» و تحلیل انتقادی رسانه و فرهنگ در بافت اسلامی به‌شمار می‌رود. از آثار کلیدی او می‌توان به «مسلمان من»، «سنت و مدرنیته» و «ایدئولوژی سلطه‌گر» اشاره کرد.', NULL, 'fa', 'ایران', 'iranian', 'a522c86f3560a7250b0198bf1d2f152bddb16ce832effde27a360bec51d83924', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-2', 'theorist', 'th-new-2', 'fatima-mernissi', 'فاتیمه مرنسی', 'Fatima Mernissi', 'theorist', 'فاتیمه مرنسی (۱۹۴۰–۲۰۱۵) جامعه‌شناس و پژوهشگر مغربی بود که در دانشکده‌ی مطالعات خاورمیانه و آفریقا دانشگاه ایالتی اوهایو تدریس می‌کرد. او بنیان‌گذار «فمینیسم اسلامی» است و به تحلیل انتقادی رسانه و گفتمان در جوامع اسلامی پرداخته است. از آثار کلیدی او «The Veil and the Male Elite» (1991)، «Islam and Women: Religious Writings» (1993) و «Dreams of Trespass» (2001) است.', NULL, 'fa', 'مغرب', 'islamic_middle_east', '19c184689036ae5704812e158169821f5fccafe0d9b32c452ada11fb23f3fa7b', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-3', 'theorist', 'th-new-3', 'ali-shadid', 'علی شادید', 'Ali Shadid', 'theorist', 'علی شادید پژوهشگر رسانه و اسلام در هلند است. او پیشگام پژوهش «رسانه و اسلام» و تحلیل تصویرسازی رسانه‌ای غرب از اسلام و مسلمانان‌هاست. آثار کلیدی او شامل «Berichtgeving over moslims en de islam in de westerse media: Beeldvorm» (1996) و «Muslims and the Media» (2005) است.', NULL, 'fa', 'هولند', 'international', '3c46d99bf15460e6d7b49bee01405d242ed0db9c34543c6ec553a6978ad252f2', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-4', 'theorist', 'th-new-4', 'hani-khamis', 'هانی خمیس', 'Hani Khamis', 'theorist', 'هانی خمیس پژوهشگر رسانه و رسانه‌های اسلامی در دانشگاه لندن شرقی است. او مرجع اصلی مطالعات «رسانه در جهان اسلامی» است و به اقتصاد رسانه و رسانه و سیاست در جهان اسلام پرداخته است. از آثار کلیدی او می‌توان به فصل‌های متعددی در مجموعه‌های معتبر درباره‌ی «Media in the Islamic World» اشاره کرد.', NULL, 'fa', 'بریتانیا', 'international', '6cb98e16449f15ad2e90b5ba8f4ac0046b597cc6c696701f0766f99e4425d179', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-5', 'theorist', 'th-new-5', 'hasan-habib', 'حسن حبیب', 'Hasan Habib', 'theorist', 'حسن حبیب پژوهشگر رسانه در حوزه‌ی لبنان و خاورمیانه است که در مجله‌ی Communications & Strategies منتشر کرده است. او به رسانه در خاورمیانه و رابطه‌ی رسانه و سیاست می‌پردازد. اثر کلیدی او «Lebanon... Notwithstanding» (Communications & Strategies) است. توجه: نام او در Crossref با «Hasan Habib» بازیکن پوکر در تضاد است و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'fa', 'لبنان', 'islamic_middle_east', '0ea05e2ddf4990e658e791302646621a647e65897548927332278b8292e83a89', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-6', 'theorist', 'th-new-6', 'abdullahi-an-na-im', 'عبداللهی آن‌نعیم', 'Abdullahi An-Na''im', 'theorist', 'عبداللهی آن‌نعیم استاد حقوق در دانشگاه اموری (Stewart McKelvey Professor of Law) است. او مهم‌ترین نظریه‌پرداز «حقوق بشر از دیدگاه اسلامی» و پل ارتباطی میان خلأ حقوق رسانه و خلأ اسلامی به‌شمار می‌رود. از آثار کلیدی او «Islam and Human Rights: Beyond the Universality Debate» (1992) و «Toward an Islamic Reformation» (2008) است.', NULL, 'fa', 'آمریکا', 'international', '25924e33c9cd88ad98ca4539effbee191e69b65f66fc49f4b89c335f24a95dfc', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-7', 'theorist', 'th-new-7', 'yasamin-molana', 'یاسمین مولانا', 'Yasamin Molana', 'theorist', 'یاسمین مولانا پژوهشگر رسانه و محیط‌زیست در دانشگاه فرا (ایتالیا) است. او یکی از معدود نظریه‌پردازان ایرانیِ قابل‌تأیید با DOI است (هم‌نویس مقاله‌ی MDPI 2026) و به روزنامه‌نگاری پایدار و محیطی و رسانه در ایران می‌پردازد. اثر کلیدی او «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) است که با Mehrdad Ahmadi و Antonio López هم‌نویسی شده است.', NULL, 'fa', 'ایران', 'iranian', 'af46331ef552bf746b13fd04616b5561a8b490ac3dbada6fb06800fa5a4d9e22', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-8', 'theorist', 'th-new-8', 'mehrdad-ahmadi', 'مهرداد احمدی', 'Mehrdad Ahmadi', 'theorist', 'مهرداد احمدی پژوهشگر ایرانی در حوزه‌ی ارتباطات محیطی و رسانه و توسعه پایدار است. او هم‌نویس مقاله‌ی «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) با Yasamin Molana و Antonio López است و دومین نظریه‌پرداز ایرانیِ قابل‌تأیید با DOI به‌شمار می‌رود.', NULL, 'fa', 'ایران', 'iranian', 'e1713af72bb84785ad5cfcc40675a51dbf737cfa767b9b700c5e6eff450d7772', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-9', 'theorist', 'th-new-9', 'danah-boyd', 'دانا بوید', 'danah boyd', 'theorist', 'دانا بوید پژوهشگر ارتباطات و فناوری در دانشگاه کورنل است. او یکی از برجسته‌ترین نظریه‌پردازان دیجیتال و پلتفرم پس از سال ۲۰۰۰ است. آثار کلیدی او شامل «It''s Complicated: The Social Lives of Networked Teens» (2014) و «Zuckerberg''s Dilemma» (2015) است.', NULL, 'fa', 'آمریکا', 'international', '36901bd40e8908a715266a40d0a767aaaa9d97314dad1774bd9da061b948d214', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-10', 'theorist', 'th-new-10', 'jose-van-dijck', 'خوزه وان دیک', 'José van Dijck', 'theorist', 'خوزه وان دیک نویسنده‌ی برجسته‌ی مطالعات رسانه و ارتباطات در دانشگاه اوترخت است. او مرجع اصلی مطالعات «جامعه‌ی پلتفرمی» است. آثار کلیدی او شامل «The Culture of Connectivity» (2013)، «The Platform Society» (2019) و «Tracing Twitter» (2013) است.', NULL, 'fa', 'هلند', 'international', '7401f24ca054d9149abd4763f144b2f1932b88f066f07841f5e4d3137ca71e26', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-11', 'theorist', 'th-new-11', 'ulises-mejias', 'اولیس میخیاس', 'Ulises Mejias', 'theorist', 'اولیس میخیاس پژوهشگر در دانشکده‌ی ارتباطات دانشگاه جورج ماسون است. او بنیان‌گذار مفهوم «استعمار داده» (Data Colonialism) و پلی میان خلأ دیجیتال و خلأ پسااستعماری به‌شمار می‌رود. آثار کلیدی او شامل «Data Colonialism» (2018) و «A Decolonial Data Ethics» (2018) است.', NULL, 'fa', 'آمریکا', 'international', '7ed14929d07f65014a69e6d240a4bedbebbc3b213c3b135cd9c9d679c9ef7891', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-12', 'theorist', 'th-new-12', 'mark-andrejevic', 'مارک اندرژویچ', 'Mark Andrejevic', 'theorist', 'مارک اندرژویچ پژوهشگر در دانشکده‌ی ارتباطات و رسانه‌ی دانشگاه سیدنی است. او نظریه‌پرداز اصلی «نظارت دیجیتال» و اقتصاد داده‌ای است. آثار کلیدی او شامل «Reality TV» (2008)، «The Work of Networks» (2013) و «Proximity Media» (2020) است.', NULL, 'fa', 'استرالیا', 'international', 'd50ba6bdc3eb5f36ebb914e28cc25655a94d0f7715e896c464bd8a920dcdf44f', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-13', 'theorist', 'th-new-13', 'viktor-mayer-schonberger', 'ویکتور مایر-شونبرگر', 'Viktor Mayer-Schönberger', 'theorist', 'ویکتور مایر-شونبرگر پژوهشگر در مؤسسه‌ی اینترنت آکسفورد است. او مرجع اصلی «حقوق بزرگ‌داده» و «حق فراموش‌شدن» است. آثار کلیدی او شامل «Big Data: A Revolution That Will Transform Us» (2013) و «Delete» (2018) است.', NULL, 'fa', 'بریتانیا', 'international', '5eafecfe68eb2b1c99d1b08edead1d572dfa3d37cc6ced1709b2c4d35d002694', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-14', 'theorist', 'th-new-14', 'shoshana-zuboff', 'شوشانا زبوف', 'Shoshana Zuboff', 'theorist', 'شوشانا زبوف پژوهشگر در مدرسه‌ی کندی هاروارد است. او بنیان‌گذار مفهوم «اقتصاد نظارتی» (Surveillance Capitalism) و مرجع اصلی خلأ دیجیتال و اخلاق/تنظیم به‌شمار می‌رود. اثر کلیدی او «The Age of Surveillance Capitalism» (2019) است.', NULL, 'fa', 'آمریکا', 'international', '52fd5e6f64d7fa42dc613767b5a7203991feda7552ac1233d3a6a85e70ab3b23', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-15', 'theorist', 'th-new-15', 'kian-tajbakhsh', 'کیان تجب‌خواه', 'Kian Tajbakhsh', 'theorist', 'کیان تجب‌خواه پژوهشگر رسانه و دین/میانه‌شرق در دانشگاه کالیفرنیا است. او به رسانه در جهان اسلام و رسانه و سیاست میانه‌شرق می‌پردازد. اثر کلیدی او «Media in the Islamic World: Introduction» (Social Research, 2003) است.', NULL, 'fa', 'آمریکا', 'international', 'd09e5ffaab5cb515ffcc9506c4b1ccfb7b21beab3f83ec68fb7fb35166a217af', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-16', 'theorist', 'th-new-16', 'mehdi-semati', 'مهدی سِمتی', 'Mehdi Semati', 'theorist', 'مهدی سِمتی پژوهشگر رسانه و سیاست در ایران است. او به فناوری‌های رسانه و سیاست در ایران می‌پردازد و پژوهشگر ایرانیِ قابل‌تأیید با DOI است. اثر کلیدی او فصل «Media Technologies and Politics in Iran» در کتاب «The Handbook of Media and Culture in the Middle East» (2023) است.', NULL, 'fa', 'ایران', 'iranian', '4d45130a28833b0c0d325741b8c87fd35c706a36be9fbcf343b9e8ccab64827b', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-17', 'theorist', 'th-new-17', 'kian-wehbe', 'کیان وهبه', 'Kian Wehbe', 'theorist', 'کیان وهبه پژوهشگر مطالعات خاورمیانه و رسانه در دانشگاه تورنتو است. او به رسانه و میانه‌شرق و سانسور رسانه‌ای می‌پردازد. توجه: نام او در Crossref با چندین «Wehbe» دیگر (پزشک/مهندسی) در تضاد است و آثار رسانه‌ایِ مشخصی به‌راحتی یافت نشد؛ تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'fa', 'لبنان', 'islamic_middle_east', '1706fe5f76b982d98d3bdb99b930136a686b8643a7b36a8d527fee219ae02b62', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-18', 'theorist', 'th-new-18', 'nasser-abbaspour', 'ناصر عباس‌پور', 'Nasser Abbaspour', 'theorist', 'ناصر عباس‌پور پژوهشگر رسانه و سیاست در ایران است. او به سیاست رسانه و رسانه در ایران می‌پردازد و مقالاتی درباره‌ی سیاست رسانه در ایران در مجلات معتبر منتشر کرده است. توجه: در فهرست قبلی با علامت «نیازمند بررسی» ثبت شده بود و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'fa', 'ایران', 'iranian', '3e3a75e8fa4686f751ac3f480e1861adb28eb5e4fe653df45a7a9df0ca092eaa', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-19', 'theorist', 'th-new-19', 'sara-talebian', 'سارا طالبیان', 'Sara Talebian', 'theorist', 'سارا طالبیان پژوهشگر رسانه و سیاست در مجله‌ی Global Media and Communication است. او به سیاست رسانه پخش در ایران می‌پردازد. اثر کلیدی او «Iran''s Broadcasting Policy» (Global Media and Communication, 2020) است.', NULL, 'fa', 'ایران', 'iranian', '877631915013c728ab026ec51bf404889200bd757b154294ea778cf8183f98ad', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-theorist-20', 'theorist', 'th-new-20', 'david-m-faris', 'دیوید م. فاریس', 'David M. Faris', 'theorist', 'دیوید م. فاریس پژوهشگر شبکه‌های اجتماعی و خاورمیانه در دانشگاه کارنگی ملون است که با هم‌نویس ایرانی‌اش Babak Rahimi همکاری می‌کند. او مرجع اصلی «شبکه‌های اجتماعی و خاورمیانه» است. اثر کلیدی او «The New Arab Activism» (2015) است.', NULL, 'fa', 'آمریکا', 'international', '8312a1e4204cec93fece8992e0ce15928722dcf07bc5628e27eae77ffa73782e', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-1', 'theorist', 'علی شریعتی', 'Ali Shariati', 'ali-shariati', 'ایران', 'iranian', NULL, 'ایران', 'جامعه‌شناسی دین، انقلاب اسلامی، گفتمان انتقادی رسانه/فرهنگ', 'بازگشت به اصل / تحلیل انتقادی رسانه و فرهنگ', '["https://upload.wikimedia.org/wikipedia/commons/b/b8/Dr_Ali_Shariati.jpg", "https://upload.wikimedia.org/wikipedia/commons/1/1c/ALI_SHARIATI.jpg"]', 'علی شریعتی (۱۹۳۳–۱۹۷۷) جامعه‌شناس، فیلسوف و پژوهشگر ایرانی با مدرک دکترای جامعه‌شناسی از دانشگاه پاریس است. او از مهم‌ترین نظریه‌پردازان ایرانیِ «بازگشت به اصل» و تحلیل انتقادی رسانه و فرهنگ در بافت اسلامی به‌شمار می‌رود. از آثار کلیدی او می‌توان به «مسلمان من»، «سنت و مدرنیته» و «ایدئولوژی سلطه‌گر» اشاره کرد.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-2', 'theorist', 'فاتیمه مرنسی', 'Fatima Mernissi', 'fatima-mernissi', 'مغرب', 'islamic_middle_east', NULL, 'مغرب', 'مطالعات زنان و اسلام، جامعه‌شناسی رسانه، فمینیسم اسلامی', 'فمینیسم اسلامی / تحلیل انتقادی رسانه و گفتمان', '["https://upload.wikimedia.org/wikipedia/commons/d/da/Fatima_Mernissi_%281940-2015%29_P8010006.jpg"]', 'فاتیمه مرنسی (۱۹۴۰–۲۰۱۵) جامعه‌شناس و پژوهشگر مغربی بود که در دانشکده‌ی مطالعات خاورمیانه و آفریقا دانشگاه ایالتی اوهایو تدریس می‌کرد. او بنیان‌گذار «فمینیسم اسلامی» است و به تحلیل انتقادی رسانه و گفتمان در جوامع اسلامی پرداخته است. از آثار کلیدی او «The Veil and the Male Elite» (1991)، «Islam and Women: Religious Writings» (1993) و «Dreams of Trespass» (2001) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-3', 'theorist', 'علی شادید', 'Ali Shadid', 'ali-shadid', 'هولند', 'international', NULL, 'هولند', 'تصویرسازی رسانه‌ای از اسلام و مسلمانان، رسانه و دین', 'رسانه و اسلام / تصویرسازی رسانه‌ای از مسلمانان', '[]', 'علی شادید پژوهشگر رسانه و اسلام در هلند است. او پیشگام پژوهش «رسانه و اسلام» و تحلیل تصویرسازی رسانه‌ای غرب از اسلام و مسلمانان‌هاست. آثار کلیدی او شامل «Berichtgeving over moslims en de islam in de westerse media: Beeldvorm» (1996) و «Muslims and the Media» (2005) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-4', 'theorist', 'هانی خمیس', 'Hani Khamis', 'hani-khamis', 'بریتانیا', 'international', NULL, 'بریتانیا', 'رسانه‌های اسلامی، اقتصاد رسانه در جهان اسلام، رسانه و سیاست', 'رسانه در جهان اسلامی', '[]', 'هانی خمیس پژوهشگر رسانه و رسانه‌های اسلامی در دانشگاه لندن شرقی است. او مرجع اصلی مطالعات «رسانه در جهان اسلامی» است و به اقتصاد رسانه و رسانه و سیاست در جهان اسلام پرداخته است. از آثار کلیدی او می‌توان به فصل‌های متعددی در مجموعه‌های معتبر درباره‌ی «Media in the Islamic World» اشاره کرد.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-5', 'theorist', 'حسن حبیب', 'Hasan Habib', 'hasan-habib', 'لبنان', 'islamic_middle_east', NULL, 'لبنان', 'رسانه در خاورمیانه، رسانه و سیاست', 'رسانه در خاورمیانه / رسانه و سیاست', '[]', 'حسن حبیب پژوهشگر رسانه در حوزه‌ی لبنان و خاورمیانه است که در مجله‌ی Communications & Strategies منتشر کرده است. او به رسانه در خاورمیانه و رابطه‌ی رسانه و سیاست می‌پردازد. اثر کلیدی او «Lebanon... Notwithstanding» (Communications & Strategies) است. توجه: نام او در Crossref با «Hasan Habib» بازیکن پوکر در تضاد است و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-6', 'theorist', 'عبداللهی آن‌نعیم', 'Abdullahi An-Na''im', 'abdullahi-an-na-im', 'آمریکا', 'international', NULL, 'آمریکا', 'حقوق بشر اسلامی، حقوق بین‌الملل و شریعت، حقوق رسانه/حقوقی', 'حقوق بشر از دیدگاه اسلامی', '[]', 'عبداللهی آن‌نعیم استاد حقوق در دانشگاه اموری (Stewart McKelvey Professor of Law) است. او مهم‌ترین نظریه‌پرداز «حقوق بشر از دیدگاه اسلامی» و پل ارتباطی میان خلأ حقوق رسانه و خلأ اسلامی به‌شمار می‌رود. از آثار کلیدی او «Islam and Human Rights: Beyond the Universality Debate» (1992) و «Toward an Islamic Reformation» (2008) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-7', 'theorist', 'یاسمین مولانا', 'Yasamin Molana', 'yasamin-molana', 'ایران', 'iranian', NULL, 'ایران', 'روزنامه‌نگاری پایدار/محیطی، رسانه در ایران، رسانه و توسعه', 'رسانه پایدار (مدل یکپارچه برای روزنامه‌نگاری محیطی)', '[]', 'یاسمین مولانا پژوهشگر رسانه و محیط‌زیست در دانشگاه فرا (ایتالیا) است. او یکی از معدود نظریه‌پردازان ایرانیِ قابل‌تأیید با DOI است (هم‌نویس مقاله‌ی MDPI 2026) و به روزنامه‌نگاری پایدار و محیطی و رسانه در ایران می‌پردازد. اثر کلیدی او «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) است که با Mehrdad Ahmadi و Antonio López هم‌نویسی شده است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-8', 'theorist', 'مهرداد احمدی', 'Mehrdad Ahmadi', 'mehrdad-ahmadi', 'ایران', 'iranian', NULL, 'ایران', 'ارتباطات محیطی، رسانه و توسعه پایدار', 'رسانه پایدار / توسعه پایدار', '[]', 'مهرداد احمدی پژوهشگر ایرانی در حوزه‌ی ارتباطات محیطی و رسانه و توسعه پایدار است. او هم‌نویس مقاله‌ی «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) با Yasamin Molana و Antonio López است و دومین نظریه‌پرداز ایرانیِ قابل‌تأیید با DOI به‌شمار می‌رود.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-9', 'theorist', 'دانا بوید', 'danah boyd', 'danah-boyd', 'آمریکا', 'international', NULL, 'آمریکا', 'شبکه‌های اجتماعی، فرهنگ دیجیتال، اخلاق داده', 'فرهنگ دیجیتال / اخلاق داده', '["https://upload.wikimedia.org/wikipedia/commons/0/05/Danah_boyd_and_Lucy_Suchman_%283348580261%29.jpg", "https://upload.wikimedia.org/wikipedia/commons/5/52/Danah_boyd_crop.jpg"]', 'دانا بوید پژوهشگر ارتباطات و فناوری در دانشگاه کورنل است. او یکی از برجسته‌ترین نظریه‌پردازان دیجیتال و پلتفرم پس از سال ۲۰۰۰ است. آثار کلیدی او شامل «It''s Complicated: The Social Lives of Networked Teens» (2014) و «Zuckerberg''s Dilemma» (2015) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-10', 'theorist', 'خوزه وان دیک', 'José van Dijck', 'jose-van-dijck', 'هلند', 'international', NULL, 'هلند', 'پلتفرم‌های اجتماعی، اقتصاد دیجیتال، تاریخ فناوری رسانه', 'جامعه پلتفرمی', '[]', 'خوزه وان دیک نویسنده‌ی برجسته‌ی مطالعات رسانه و ارتباطات در دانشگاه اوترخت است. او مرجع اصلی مطالعات «جامعه‌ی پلتفرمی» است. آثار کلیدی او شامل «The Culture of Connectivity» (2013)، «The Platform Society» (2019) و «Tracing Twitter» (2013) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-11', 'theorist', 'اولیس میخیاس', 'Ulises Mejias', 'ulises-mejias', 'آمریکا', 'international', NULL, 'آمریکا', 'استعمار داده، اخلاق داده، نظارت دیجیتال', 'استعمار داده (Data Colonialism)', '[]', 'اولیس میخیاس پژوهشگر در دانشکده‌ی ارتباطات دانشگاه جورج ماسون است. او بنیان‌گذار مفهوم «استعمار داده» (Data Colonialism) و پلی میان خلأ دیجیتال و خلأ پسااستعماری به‌شمار می‌رود. آثار کلیدی او شامل «Data Colonialism» (2018) و «A Decolonial Data Ethics» (2018) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-12', 'theorist', 'مارک اندرژویچ', 'Mark Andrejevic', 'mark-andrejevic', 'استرالیا', 'international', NULL, 'استرالیا', 'نظارت دیجیتال، اقتصاد اطلاعات، رسانه و فناوری', 'نظارت دیجیتال / اقتصاد داده‌ای', '[]', 'مارک اندرژویچ پژوهشگر در دانشکده‌ی ارتباطات و رسانه‌ی دانشگاه سیدنی است. او نظریه‌پرداز اصلی «نظارت دیجیتال» و اقتصاد داده‌ای است. آثار کلیدی او شامل «Reality TV» (2008)، «The Work of Networks» (2013) و «Proximity Media» (2020) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-13', 'theorist', 'ویکتور مایر-شونبرگر', 'Viktor Mayer-Schönberger', 'viktor-mayer-schonberger', 'بریتانیا', 'international', NULL, 'بریتانیا', 'حقوق داده، حریم خصوصی، حقوق بزرگ‌داده، تنظیم دیجیتال', 'حقوق بزرگ‌داده / حق فراموش‌شدن', '["https://upload.wikimedia.org/wikipedia/commons/9/96/Viktor_Mayer-Sch%C3%B6nberger_%281%29.jpg", "https://upload.wikimedia.org/wikipedia/commons/e/ee/Viktor_Mayer-Sch%C3%B6nberger_Big_Data_Forum_20140610_3.jpg"]', 'ویکتور مایر-شونبرگر پژوهشگر در مؤسسه‌ی اینترنت آکسفورد است. او مرجع اصلی «حقوق بزرگ‌داده» و «حق فراموش‌شدن» است. آثار کلیدی او شامل «Big Data: A Revolution That Will Transform Us» (2013) و «Delete» (2018) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-14', 'theorist', 'شوشانا زبوف', 'Shoshana Zuboff', 'shoshana-zuboff', 'آمریکا', 'international', NULL, 'آمریکا', 'اقتصاد نظارتی، نظارت دیجیتال، اخلاق فناوری', 'سرمایه‌داری نظارتی (Surveillance Capitalism)', '["https://upload.wikimedia.org/wikipedia/commons/8/88/Shoshana_Zuboff_at_Alexander_von_Humboldt_Institut.jpg"]', 'شوشانا زبوف پژوهشگر در مدرسه‌ی کندی هاروارد است. او بنیان‌گذار مفهوم «اقتصاد نظارتی» (Surveillance Capitalism) و مرجع اصلی خلأ دیجیتال و اخلاق/تنظیم به‌شمار می‌رود. اثر کلیدی او «The Age of Surveillance Capitalism» (2019) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-15', 'theorist', 'کیان تجب‌خواه', 'Kian Tajbakhsh', 'kian-tajbakhsh', 'آمریکا', 'international', NULL, 'آمریکا', 'رسانه در جهان اسلام، رسانه و سیاست میانه‌شرق', 'رسانه در جهان اسلام', '[]', 'کیان تجب‌خواه پژوهشگر رسانه و دین/میانه‌شرق در دانشگاه کالیفرنیا است. او به رسانه در جهان اسلام و رسانه و سیاست میانه‌شرق می‌پردازد. اثر کلیدی او «Media in the Islamic World: Introduction» (Social Research, 2003) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-16', 'theorist', 'مهدی سِمتی', 'Mehdi Semati', 'mehdi-semati', 'ایران', 'iranian', NULL, 'ایران', 'فناوری‌های رسانه و سیاست در ایران', 'فناوری رسانه و سیاست در ایران', '[]', 'مهدی سِمتی پژوهشگر رسانه و سیاست در ایران است. او به فناوری‌های رسانه و سیاست در ایران می‌پردازد و پژوهشگر ایرانیِ قابل‌تأیید با DOI است. اثر کلیدی او فصل «Media Technologies and Politics in Iran» در کتاب «The Handbook of Media and Culture in the Middle East» (2023) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-17', 'theorist', 'کیان وهبه', 'Kian Wehbe', 'kian-wehbe', 'لبنان', 'islamic_middle_east', NULL, 'لبنان', 'رسانه و میانه‌شرق، سانسور رسانه‌ای', 'رسانه و میانه‌شرق / سانسور رسانه‌ای', '[]', 'کیان وهبه پژوهشگر مطالعات خاورمیانه و رسانه در دانشگاه تورنتو است. او به رسانه و میانه‌شرق و سانسور رسانه‌ای می‌پردازد. توجه: نام او در Crossref با چندین «Wehbe» دیگر (پزشک/مهندسی) در تضاد است و آثار رسانه‌ایِ مشخصی به‌راحتی یافت نشد؛ تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-18', 'theorist', 'ناصر عباس‌پور', 'Nasser Abbaspour', 'nasser-abbaspour', 'ایران', 'iranian', NULL, 'ایران', 'سیاست رسانه و رسانه در ایران', 'سیاست رسانه در ایران', '[]', 'ناصر عباس‌پور پژوهشگر رسانه و سیاست در ایران است. او به سیاست رسانه و رسانه در ایران می‌پردازد و مقالاتی درباره‌ی سیاست رسانه در ایران در مجلات معتبر منتشر کرده است. توجه: در فهرست قبلی با علامت «نیازمند بررسی» ثبت شده بود و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-th-new-19', 'theorist', 'سارا طالبیان', 'Sara Talebian', 'sara-talebian', 'ایران', 'iranian', NULL, 'ایران', 'سیاست رسانه پخش در ایران', 'سیاست رسانه پخش ایران', '[]', 'سارا طالبیان پژوهشگر رسانه و سیاست در مجله‌ی Global Media and Communication است. او به سیاست رسانه پخش در ایران می‌پردازد. اثر کلیدی او «Iran''s Broadcasting Policy» (Global Media and Communication, 2020) است.', NULL, 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
