INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-1', 'journal', 'journal-new-1', 'new-journal-1', 'رسانه‌های نو و جامعه', 'New Media & Society', 'journal', 'New Media & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات رسانه‌های نو است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش‌های رسانه‌های دیجیتال، فناوری و جامعه و تحلیل رسانه‌های نو به‌شمار می‌رود. با ISSN 1461-4448 (چاپی) و 1461-7315 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده است و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/nus', 'en', NULL, 'international', '8685bdaff2ba3b4e06c8b46b015a476bf1fa7d351ae0254291254cdd8ff6a838', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-2', 'journal', 'journal-new-2', 'new-journal-2', 'رسانه، فرهنگ و جامعه', 'Media, Culture & Society', 'journal', 'Media, Culture & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات فرهنگی رسانه، جامعه‌شناسی رسانه و رسانه و فرهنگ عامه است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی «جامعه‌شناسی رسانه» و «رسانه و فرهنگ» به‌شمار می‌رود. با ISSN 0163-4437 (چاپی) و 1460-3675 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/mcs', 'en', NULL, 'international', '04b1bb2325a594c2932cdcebe3832ce05ca268aa09a0451a3ee679b100241530', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-3', 'journal', 'journal-new-3', 'new-journal-3', 'همگرایی: مجلهٔ بین‌المللی پژوهش فناوری‌های رسانه‌های نو', 'Convergence: The International Journal of Research into New Media Technologies', 'journal', 'Convergence: The International Journal of Research into New Media Technologies مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی فناوری‌های رسانه‌های نو، همگرایی رسانه‌ای، آینده‌ی رسانه و رسانه و فناوری است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش فناوری‌های رسانه‌های نو به‌شمار می‌رود. با ISSN 1354-8565 (چاپی) و 1748-7382 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/con', 'en', NULL, 'international', 'd807d7302524b3e3b13d49bd8ea77c24d88d3e8be62474d79cdfccffdb14f79d', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-4', 'journal', 'journal-new-4', 'new-journal-4', 'مطالعات روزنامه‌نگاری', 'Journalism Studies', 'journal', 'Journalism Studies مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی پژوهش روزنامه‌نگاری، روزنامه‌نگاری تطبیقی، اقتصاد روزنامه‌نگاری و آینده‌ی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری تطبیقی» و «پارادایم‌های روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1461-670X (چاپی) و 1469-9699 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rjoc20', 'en', NULL, 'international', 'e309ddaa82a2038370a6ac972b76e013a51051564249e2443cb9e1dcb81a4f7a', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-5', 'journal', 'journal-new-5', 'new-journal-5', 'روزنامه‌نگاری دیجیتال', 'Digital Journalism', 'journal', 'Digital Journalism مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی روزنامه‌نگاری دیجیتال، روزنامه‌نگاری داده‌محور، رسانه‌های اجتماعی و خبر، الگوریتم و خبر است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری دیجیتال» و «روزنامه‌نگاری خودکار» است و پوشش دقیقی از مدخل‌های پلتفرمی سایت ارائه می‌دهد. با ISSN 2167-0811 (چاپی) و 2167-082X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rdij20', 'en', NULL, 'international', '4a44c4c2119a04a8cfd6df772dc0e5e60f313c44bd27fe3f85c7d21381cf7f58', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-6', 'journal', 'journal-new-6', 'new-journal-6', 'عمل روزنامه‌نگاری', 'Journalism Practice', 'journal', 'Journalism Practice مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی عمل روزنامه‌نگاری، اخلاق روزنامه‌نگاری، رسانه‌های اجتماعی و خبر و پژوهش عملی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «عمل روزنامه‌نگاری» و «اخلاق روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1751-2786 (چاپی) و 1751-2794 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rjpr20', 'en', NULL, 'international', 'f0174336715482e1a27e3e0f435f97994faa12a9d9806a3825cf9f40ff052dfc', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-7', 'journal', 'journal-new-7', 'new-journal-7', 'مجلهٔ بین‌المللی ارتباطات', 'International Journal of Communication', 'journal', 'International Journal of Communication (IJOC) مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی پژوهش ارتباطات بین‌المللی، روش‌شناسی ارتباطات، ارتباطات و فناوری است که توسط USC Annenberg Press به‌صورت رایگان (Open Access) منتشر می‌شود. این مجله مرجع اصلی «روش‌شناسی ارتباطات» و «ارتباطات محاسباتی» به‌شمار می‌رود. با ISSN 1932-8036 (فقط الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://ijoc.org', 'en', NULL, 'international', '1ec35ffe3ff7d195f8196c4a9eaed71df9107e3c1cb2932c8d44c6871e6e8694', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-8', 'journal', 'journal-new-8', 'new-journal-8', 'پیام (پژوهش‌های علوم انسانی)', 'Peyam: Humanities Studies', 'journal', 'Peyam (پیام) — پژوهش‌های علوم انسانی مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی علوم انسانی، ارتباطات، جامعه‌شناسی و فرهنگ است که توسط پژوهشگاه علوم انسانی و مطالعات فرهنگی منتشر می‌شود. این مجله مرجع اصلی «ارتباطات در بافت ایران» به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در DOAJ/CrossRef/Wikidata، ISSN و وضعیت نمایه‌ی بین‌المللی (Scopus/ESCI) هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'fa', 'ایران', 'iranian', 'b0956ee200fe3b75f1a47d503e0a3c4db74d2dd36e3380eb4ac08a1f265242ce', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-9', 'journal', 'journal-new-9', 'new-journal-9', 'فرهنگ رسانه', 'Farhang-e Rasaneh (Media Culture)', 'journal', 'Farhang-e Rasaneh (فرهنگ رسانه) مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی فرهنگ رسانه، مطالعات فرهنگی و ارتباطات است که توسط پژوهشگاه فرهنگ، هنر و ارتباطات منتشر می‌شود. این مجله مرجع اصلی «فرهنگ رسانه» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'fa', 'ایران', 'iranian', '07dbf62741287a576e1a524b10efe0eda9134b30ba59797e1eaf295cf789c789', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-10', 'journal', 'journal-new-10', 'new-journal-10', 'رسانه و فرهنگ', 'Rasaneh-ye Farhang (Media and Culture)', 'journal', 'Rasaneh-ye Farhang (رسانه و فرهنگ) مجلهٔ شناخته‌شده‌ی ایرانی در حوزه‌ی رسانه و فرهنگ، ارتباطات و مطالعات فرهنگی است که ناشر آن احتمالاً دانشگاه تهران است (نیازمند تأیید). این مجله مرجع اصلی «رسانه و فرهنگ» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ناشر، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'fa', 'ایران', 'iranian', '38c4b6029233bad5e15545ee79463fc24a16d7deda848323a9b48689dae768a3', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-11', 'journal', 'journal-new-11', 'new-journal-11', 'مطالعات فرهنگ و ارتباطات', NULL, 'journal', 'مطالعات فرهنگ و ارتباطات مجلهٔ فارسی در حوزه‌ی فرهنگ، ارتباطات، مطالعات فرهنگی و رسانه است که ناشر آن احتمالاً پژوهشگاه فرهنگ، هنر و ارتباطات است (نیازمند تأیید). این مجله مرجع اصلی «مطالعات فرهنگی» در بافت ایرانی به‌شمار می‌رود. هشدار: ممکن است با مجلهٔ انگلیسی «Journal of Culture-Communication Studies (JCCS)» (ردیف ۲۴ فهرست ۲۵ مجلهٔ موجود) تکراری باشد و در صورت تأیید تداخل باید حذف شود. پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'fa', 'ایران', 'iranian', '6a0233c45cc38e3a9ceaa9591ec0746a787d8557520e3716612d916682a5a5da', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-12', 'journal', 'journal-new-12', 'new-journal-12', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران)', NULL, 'journal', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران) مجلهٔ فارسی در حوزه‌ی فرهنگ رسانه و ارتباطات است که توسط انجمن فرهنگی رسانه ایران منتشر می‌شود. این کم‌اعتبارترین مورد فهرست ۱۵ مجلهٔ جدید است؛ اطلاعات آن ناقص است و ممکن است با مجلهٔ «Farhang-e Rasaneh (فرهنگ رسانه)» (ردیف ۲.۹) تداخل داشته باشد. پیش از استفاده باید از داخل ایران تأیید شود و در صورت عدم‌تأیید، این مورد باید حذف شود.', NULL, 'fa', 'ایران', 'iranian', 'ece0ee180d27b153841ad81c9eeec2d86d7967ef204938ba92a62a9a35a8dc68', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-13', 'journal', 'journal-new-13', 'new-journal-13', 'اخلاق رسانه', 'Journal of Media Ethics', 'journal', 'Journal of Media Ethics مجلهٔ بین‌المللی و Q3 (SCImago و Web of Science — Communication / Ethics) در حوزه‌ی اخلاق رسانه، اخلاق روزنامه‌نگاری، حریم خصوصی و حقوق رسانه است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «اخلاق رسانه» و پوشش‌دهنده‌ی خلأ مجلات اخلاق رسانه است. با ISSN 2373-6992 (چاپی) و 2373-700X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/hjmc20', 'en', NULL, 'international', 'b3621a94838229ed454b41fe58c95cf21058c24682c8cc5f501125953242acd8', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-14', 'journal', 'journal-new-14', 'new-journal-14', 'مطالعات بین‌المللی خاورمیانه', 'International Journal of Middle East Studies', 'journal', 'International Journal of Middle East Studies (IJMES) مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science — Middle Eastern / Islamic Studies) در حوزه‌ی مطالعات خاورمیانه، تاریخ خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Cambridge University Press منتشر می‌شود. این مجله مرجع اصلی «مطالعات خاورمیانه» از منظر پژوهش غربی است. با ISSN 0020-7438 (چاپی) و 1471-6380 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.cambridge.org/core/journals/international-journal-of-middle-east-studies', 'en', NULL, 'international', 'd127ee0a288a1805ba2abde8f4059e6e37ac08c921a61c5075c6a661107804f8', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES ('doc-new-journal-15', 'journal', 'journal-new-15', 'new-journal-15', 'مجلهٔ خاورمیانه', 'Middle East Journal', 'journal', 'Middle East Journal مجلهٔ بین‌المللی و Q2 (SCImago و Web of Science — Middle Eastern Studies) در حوزه‌ی مطالعات خاورمیانه، سیاست خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Columbia University منتشر می‌شود. این مجله (بنیان‌گذاری ۱۹۴۷) مرجع اصلی «مطالعات خاورمیانه» از منظر تاریخی/سیاسی است. با ISSN 0026-3292 (چاپی) و 1548-9251 (الکترونیکی — نیازمند تأیید)، در Scopus، Web of Science و Scimago نمایه شده است؛ این مجله در CrossRef ثبت ندارد اما مجلهٔ معتبر دانشگاه کلمبیا است.', 'https://www.middleeastjournal.org', 'en', NULL, 'international', '70253844a2d5439a9764c288e3bb2b1000e80fb0b926054facb80f5382024456', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-1', 'journal', 'رسانه‌های نو و جامعه', 'New Media & Society', 'new-journal-1', NULL, 'international', NULL, NULL, 'مطالعات رسانه‌های نو، رسانه‌های دیجیتال، فناوری و جامعه، تحلیل رسانه‌های نو', NULL, '["https://journals.sagepub.com/home/nus/cover-image", "https://journals.sagepub.com/action/showPublicationsMenu?doi=10.1177/14614448"]', 'New Media & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات رسانه‌های نو است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش‌های رسانه‌های دیجیتال، فناوری و جامعه و تحلیل رسانه‌های نو به‌شمار می‌رود. با ISSN 1461-4448 (چاپی) و 1461-7315 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده است و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/nus', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-2', 'journal', 'رسانه، فرهنگ و جامعه', 'Media, Culture & Society', 'new-journal-2', NULL, 'international', NULL, NULL, 'مطالعات فرهنگی رسانه، جامعه‌شناسی رسانه، رسانه و فرهنگ عامه', NULL, '["https://journals.sagepub.com/home/mcs/cover-image", "https://journals.sagepub.com/action/showPublicationsMenu?doi=10.1177/01634437"]', 'Media, Culture & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات فرهنگی رسانه، جامعه‌شناسی رسانه و رسانه و فرهنگ عامه است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی «جامعه‌شناسی رسانه» و «رسانه و فرهنگ» به‌شمار می‌رود. با ISSN 0163-4437 (چاپی) و 1460-3675 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/mcs', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-3', 'journal', 'همگرایی: مجلهٔ بین‌المللی پژوهش فناوری‌های رسانه‌های نو', 'Convergence: The International Journal of Research into New Media Technologies', 'new-journal-3', NULL, 'international', NULL, NULL, 'فناوری‌های رسانه‌های نو، همگرایی رسانه‌ای، آینده‌ی رسانه، رسانه و فناوری', NULL, '["https://journals.sagepub.com/home/con/cover-image", "https://journals.sagepub.com/action/showPublicationsMenu?doi=10.1177/13548565"]', 'Convergence: The International Journal of Research into New Media Technologies مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی فناوری‌های رسانه‌های نو، همگرایی رسانه‌ای، آینده‌ی رسانه و رسانه و فناوری است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش فناوری‌های رسانه‌های نو به‌شمار می‌رود. با ISSN 1354-8565 (چاپی) و 1748-7382 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://journals.sagepub.com/home/con', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-4', 'journal', 'مطالعات روزنامه‌نگاری', 'Journalism Studies', 'new-journal-4', NULL, 'international', NULL, NULL, 'پژوهش روزنامه‌نگاری، روزنامه‌نگاری تطبیقی، اقتصاد روزنامه‌نگاری، آینده‌ی روزنامه‌نگاری', NULL, '["https://www.tandfonline.com/doi/pdf/10.1080/1461670X.2014.932755", "https://www.tandfonline.com/action/showPublicationsMenu?doi=10.1080/1461670X"]', 'Journalism Studies مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی پژوهش روزنامه‌نگاری، روزنامه‌نگاری تطبیقی، اقتصاد روزنامه‌نگاری و آینده‌ی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری تطبیقی» و «پارادایم‌های روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1461-670X (چاپی) و 1469-9699 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rjoc20', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-5', 'journal', 'روزنامه‌نگاری دیجیتال', 'Digital Journalism', 'new-journal-5', NULL, 'international', NULL, NULL, 'روزنامه‌نگاری دیجیتال، روزنامه‌نگاری داده‌محور، رسانه‌های اجتماعی و خبر، الگوریتم و خبر', NULL, '["https://www.tandfonline.com/doi/pdf/10.1080/21670811.2014.932755", "https://www.tandfonline.com/action/showPublicationsMenu?doi=10.1080/21670811"]', 'Digital Journalism مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی روزنامه‌نگاری دیجیتال، روزنامه‌نگاری داده‌محور، رسانه‌های اجتماعی و خبر، الگوریتم و خبر است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری دیجیتال» و «روزنامه‌نگاری خودکار» است و پوشش دقیقی از مدخل‌های پلتفرمی سایت ارائه می‌دهد. با ISSN 2167-0811 (چاپی) و 2167-082X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'https://www.tandfonline.com/journals/rdij20', 'verified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
