INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-8', 'journal', 'پیام (پژوهش‌های علوم انسانی)', 'Peyam: Humanities Studies', 'new-journal-8', 'ایران', 'iranian', NULL, 'ایران', 'علوم انسانی، ارتباطات، جامعه‌شناسی، فرهنگ', NULL, '[]', 'Peyam (پیام) — پژوهش‌های علوم انسانی مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی علوم انسانی، ارتباطات، جامعه‌شناسی و فرهنگ است که توسط پژوهشگاه علوم انسانی و مطالعات فرهنگی منتشر می‌شود. این مجله مرجع اصلی «ارتباطات در بافت ایران» به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در DOAJ/CrossRef/Wikidata، ISSN و وضعیت نمایه‌ی بین‌المللی (Scopus/ESCI) هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-9', 'journal', 'فرهنگ رسانه', 'Farhang-e Rasaneh (Media Culture)', 'new-journal-9', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ رسانه، مطالعات فرهنگی، ارتباطات', NULL, '[]', 'Farhang-e Rasaneh (فرهنگ رسانه) مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی فرهنگ رسانه، مطالعات فرهنگی و ارتباطات است که توسط پژوهشگاه فرهنگ، هنر و ارتباطات منتشر می‌شود. این مجله مرجع اصلی «فرهنگ رسانه» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-10', 'journal', 'رسانه و فرهنگ', 'Rasaneh-ye Farhang (Media and Culture)', 'new-journal-10', 'ایران', 'iranian', NULL, 'ایران', 'رسانه و فرهنگ، ارتباطات، مطالعات فرهنگی', NULL, '[]', 'Rasaneh-ye Farhang (رسانه و فرهنگ) مجلهٔ شناخته‌شده‌ی ایرانی در حوزه‌ی رسانه و فرهنگ، ارتباطات و مطالعات فرهنگی است که ناشر آن احتمالاً دانشگاه تهران است (نیازمند تأیید). این مجله مرجع اصلی «رسانه و فرهنگ» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ناشر، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-11', 'journal', 'مطالعات فرهنگ و ارتباطات', NULL, 'new-journal-11', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ، ارتباطات، مطالعات فرهنگی، رسانه', NULL, '[]', 'مطالعات فرهنگ و ارتباطات مجلهٔ فارسی در حوزه‌ی فرهنگ، ارتباطات، مطالعات فرهنگی و رسانه است که ناشر آن احتمالاً پژوهشگاه فرهنگ، هنر و ارتباطات است (نیازمند تأیید). این مجله مرجع اصلی «مطالعات فرهنگی» در بافت ایرانی به‌شمار می‌رود. هشدار: ممکن است با مجلهٔ انگلیسی «Journal of Culture-Communication Studies (JCCS)» (ردیف ۲۴ فهرست ۲۵ مجلهٔ موجود) تکراری باشد و در صورت تأیید تداخل باید حذف شود. پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES ('entity-journal-new-12', 'journal', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران)', NULL, 'new-journal-12', 'ایران', 'iranian', NULL, 'ایران', 'فرهنگ رسانه، ارتباطات', NULL, '[]', 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران) مجلهٔ فارسی در حوزه‌ی فرهنگ رسانه و ارتباطات است که توسط انجمن فرهنگی رسانه ایران منتشر می‌شود. این کم‌اعتبارترین مورد فهرست ۱۵ مجلهٔ جدید است؛ اطلاعات آن ناقص است و ممکن است با مجلهٔ «Farhang-e Rasaneh (فرهنگ رسانه)» (ردیف ۲.۹) تداخل داشته باشد. پیش از استفاده باید از داخل ایران تأیید شود و در صورت عدم‌تأیید، این مورد باید حذف شود.', NULL, 'unverified', '2026-11-09 00:00:00', '2026-11-09 00:00:00');
